// -------------------------------------

// Project: DCL Web Frontend Development Automation
// NOTE: Modernized for Gulp 4/5 + ESLint 9 — see CHANGELOG.md

// -------------------------------------

// Available tasks (returned from the factory below):
// `build`, `ubuild`, `clean`, `watch`, `cat`, `sass`, `js`,
// `gulpJsLint`, `jsLint`, `minify`

// -------------------------------------

const { rimraf } = require("rimraf");
const gulp = require("gulp");
const browserSync = require("browser-sync").create();

const $gf = require("./gulpfuncs");

// Variable options and paths are separated out into the consuming
// project's gulp-config.js and passed in to us during the require.
let $conf;

// -------------------------------------
// Small helpers (replace the lodash `get` / `filter` / `flatMap`
// calls that used to come along for three one-liners).
// -------------------------------------

const get = (obj, keyPath) =>
  keyPath.split(".").reduce((o, k) => (o == null ? o : o[k]), obj);

const flattenCompact = (arrays) => arrays.filter(Boolean).flat();

function noop(cb) {
  cb();
}

/** Compile SASS files into CSS
 * @return {stream} the Node stream representing the compiled files.
 */
function lintAndCompileSASS() {
  return $gf.lintAndCompileSASS($conf.sass.sources, $conf.sass.destination);
}

// Validate the JavaScript sources
function jsLint(cb) {
  const srcs = get($conf, "js.sources");
  if (srcs === undefined) return noop(cb);

  return $gf.jsLint(srcs).then(() => cb(), cb);
}

// Produce minified JavaScript files
function js(cb) {
  const srcs = get($conf, "js.sources");
  if (srcs === undefined) return noop(cb);

  return $gf.jsMinify(srcs, $conf.js.destination).pipe(browserSync.stream());
}

// Validate the Gulp files themselves
function gulpJsLint(cb) {
  return $gf.jsLint($conf.gulp.files).then(() => cb(), cb);
}

// Gulp tasks: CSS
function catenateCSS(cb) {
  const groups = get($conf, "css.concatenate");
  if (groups === undefined) return noop(cb);

  const tasks = groups.map(({ sources, destination }) => {
    return function concatOne(fcb) {
      $gf.concatCSS(sources, destination).on("end", fcb).on("error", fcb);
    };
  });

  return gulp.parallel(...tasks)(cb);
}

function minifyCSS(cb) {
  let srcs = get($conf, "css.sources");
  if (srcs === undefined) return noop(cb);

  const exclude = get($conf, "css.exclude");
  if (exclude !== undefined) {
    srcs = srcs.concat(exclude.map((p) => `!${p}`));
  }

  return $gf.minifyCSS(srcs, $conf.css.destination).pipe(browserSync.stream());
}

function moveCSS(cb) {
  let srcs = get($conf, "css.sources");
  if (srcs === undefined) return noop(cb);

  const exclude = get($conf, "css.exclude");
  if (exclude !== undefined) {
    srcs = srcs.concat(exclude.map((p) => `!${p}`));
  }

  return $gf.moveCSS(srcs, $conf.css.destination).pipe(browserSync.stream());
}

// Gulp tasks: delete compiled files. Supports globs via rimraf's `glob` option.
async function clean() {
  const srcs = flattenCompact([
    get($conf, "product.dirs"),
    get($conf, "product.files"),
  ]);
  if (srcs.length === 0) return;

  await rimraf(srcs, { glob: true });
}

function sync(cb) {
  browserSync.init({
    files: flattenCompact([
      get($conf, "css.sources"),
      get($conf, "js.sources"),
    ]),
    proxy: {
      target: get($conf, "browserSync.proxyTarget"),
    },
    browser: ["google chrome", "firefox", "safari"],
    open: true,
  });
  cb();
}

function syncReload(cb) {
  browserSync.reload();
  cb();
}

// Record checksums of all the source files so CI/CD can later
// validate the build products against the sources.
function updateSourceChecksums(cb) {
  const checksumFile = get($conf, "product.checksums");
  if (checksumFile === undefined) return noop(cb);

  const srcs = flattenCompact([
    get($conf, "js.sources"),
    get($conf, "sass.sources"),
  ]);

  return $gf.updateSourceChecksums(srcs, checksumFile);
}

// Gulp tasks: watch and browserSync. Intentionally does not signal
// completion — this task should keep running for as long as
// `gulp watch` is alive.
function watchFiles(/* cb */) {
  const jsSrc = get($conf, "js.sources");
  if (jsSrc !== undefined) {
    gulp.watch(jsSrc, gulp.series(jsLint, js));
  }

  gulp.watch($conf.sass.sources, gulp.series(lintAndCompileSASS, minifyCSS));

  gulp.watch($conf.product.files).on("change", syncReload);
}

module.exports = (config) => {
  $conf = config;

  const build = gulp.series(
    clean,
    // Minor race condition here. If edit happens after compile
    // before checksum, it won't be detectable.
    // Work around: don't edit while compiling!
    gulp.parallel(lintAndCompileSASS, js, updateSourceChecksums, catenateCSS),
    minifyCSS,
  );

  const ubuild = gulp.series(
    clean,
    gulp.parallel(lintAndCompileSASS, js, updateSourceChecksums, catenateCSS),
    moveCSS,
  );

  const watchSync = gulp.parallel(sync, watchFiles);

  return {
    // Gulp public tasks
    clean,
    build,
    ubuild,
    default: build,
    watch: watchSync,

    // Gulp public sub-tasks
    cat: catenateCSS,
    sass: lintAndCompileSASS,
    js,
    gulpJsLint,
    jsLint,
    minify: minifyCSS,
  };
};

